foreach ($screen in $screens) {
    $name = $screen.name
    $htmlUrl = $screen.html
    $pngUrl = $screen.png + "=w" + $screen.width

    Write-Host "Fetching $name HTML..."
    curl.exe -L -f -sS --connect-timeout 10 --compressed "$htmlUrl" -o ".stitch/designs/$name.html"
    
    Write-Host "Fetching $name PNG..."
    curl.exe -L -f -sS --connect-timeout 10 --compressed "$pngUrl" -o ".stitch/designs/$name.png"
}
Write-Host "Done fetching all screens."
